CREATE TABLE public.publication_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), google_indexing_enabled boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.publication_settings TO anon, authenticated;
GRANT UPDATE ON public.publication_settings TO authenticated;
GRANT ALL ON public.publication_settings TO service_role;
ALTER TABLE public.publication_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY publication_read ON public.publication_settings FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY publication_admin_update ON public.publication_settings FOR UPDATE TO authenticated USING ((select public.has_role((select auth.uid()), 'admin')) OR (select public.is_super_admin())) WITH CHECK ((select public.has_role((select auth.uid()), 'admin')) OR (select public.is_super_admin()));
INSERT INTO public.publication_settings(id) SELECT true;
CREATE TABLE public.community_discussion_memberships (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now(), switch_allowed_at timestamptz NOT NULL DEFAULT (now() + interval '6 months'), confirmed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.community_discussion_memberships TO authenticated;
GRANT ALL ON public.community_discussion_memberships TO service_role;
ALTER TABLE public.community_discussion_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_read_self ON public.community_discussion_memberships FOR SELECT TO authenticated USING (user_id=(select auth.uid()));
CREATE INDEX community_discussion_memberships_community_idx ON public.community_discussion_memberships(community_id);
CREATE OR REPLACE FUNCTION public.is_chat_member(_chat_id uuid, _user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM chat_members WHERE chat_id=_chat_id AND user_id=_user_id) AND (NOT EXISTS(SELECT 1 FROM communities WHERE discussion_chat_id=_chat_id) OR EXISTS(SELECT 1 FROM community_discussion_memberships m JOIN communities c ON c.id=m.community_id WHERE m.user_id=_user_id AND c.discussion_chat_id=_chat_id)); $$;
CREATE OR REPLACE FUNCTION public.confirm_community_discussion(_community_id uuid, _confirmed boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _uid uuid:=auth.uid(); _chat uuid; _membership community_discussion_memberships%ROWTYPE; BEGIN IF _uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_uid::text,0)); SELECT discussion_chat_id INTO _chat FROM communities WHERE id=_community_id; IF _chat IS NULL THEN RAISE EXCEPTION 'Community has no discussion'; END IF; SELECT * INTO _membership FROM community_discussion_memberships WHERE user_id=_uid FOR UPDATE; IF _membership.community_id IS DISTINCT FROM _community_id THEN IF _confirmed IS DISTINCT FROM true THEN RAISE EXCEPTION 'Confirm that you belong to this community before joining'; END IF; IF _membership.user_id IS NOT NULL AND now() < _membership.switch_allowed_at THEN RAISE EXCEPTION 'You can only join one community. You may switch after %', to_char(_membership.switch_allowed_at,'DD Mon YYYY'); END IF; INSERT INTO community_discussion_memberships(user_id,community_id,joined_at,switch_allowed_at,confirmed_at) VALUES (_uid,_community_id,now(),now()+interval '6 months',now()) ON CONFLICT(user_id) DO UPDATE SET community_id=excluded.community_id,joined_at=excluded.joined_at,switch_allowed_at=excluded.switch_allowed_at,confirmed_at=excluded.confirmed_at; DELETE FROM chat_members WHERE user_id=_uid AND chat_id IN (SELECT discussion_chat_id FROM communities WHERE id<>_community_id AND discussion_chat_id IS NOT NULL); END IF; INSERT INTO chat_members(chat_id,user_id,role) VALUES(_chat,_uid,'member') ON CONFLICT DO NOTHING; RETURN _chat; END $$;
REVOKE EXECUTE ON FUNCTION public.confirm_community_discussion(uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.confirm_community_discussion(uuid,boolean) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.join_community_discussion(_community_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.confirm_community_discussion(_community_id,false); END $$;
REVOKE EXECUTE ON FUNCTION public.join_community_discussion(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.join_community_discussion(uuid) TO authenticated,service_role;
CREATE FUNCTION public.guard_discussion_member_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM communities WHERE discussion_chat_id=NEW.chat_id) AND NOT EXISTS(SELECT 1 FROM community_discussion_memberships m JOIN communities c ON c.id=m.community_id WHERE m.user_id=NEW.user_id AND c.discussion_chat_id=NEW.chat_id) THEN RAISE EXCEPTION 'Community confirmation is required; users can only join one community'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_discussion_member BEFORE INSERT OR UPDATE ON public.chat_members FOR EACH ROW EXECUTE FUNCTION public.guard_discussion_member_insert();
CREATE OR REPLACE FUNCTION public.ensure_news_community(_name text,_owner uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _key text:=lower(regexp_replace(trim(_name),'\s+',' ','g')); _cid uuid; _chat uuid; _title text; BEGIN IF _key='' THEN RAISE EXCEPTION 'Community name required'; END IF; SELECT id,discussion_chat_id INTO _cid,_chat FROM communities WHERE name_key=_key; _title:=initcap(regexp_replace(trim(_name),'\s+',' ','g')); IF _cid IS NULL THEN INSERT INTO communities(name,description,created_by,name_key) VALUES(_title||' Community','Local news and discussion for '||_title,_owner,_key) ON CONFLICT(name_key) WHERE name_key IS NOT NULL DO NOTHING RETURNING id INTO _cid; IF _cid IS NULL THEN SELECT id,discussion_chat_id INTO _cid,_chat FROM communities WHERE name_key=_key; END IF; END IF; IF _chat IS NULL THEN INSERT INTO chats(created_by,name,description,is_group,is_community,community_id,last_message,last_message_at) VALUES(_owner,_title||' Community','Community discussion',true,false,_cid,'Community created',now()) RETURNING id INTO _chat; UPDATE communities SET discussion_chat_id=_chat WHERE id=_cid; END IF; RETURN _cid; END $$;
ALTER TABLE public.community_news ADD COLUMN ad_image_path text, ADD COLUMN watermarked boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.review_community_news(_id uuid,_approve boolean,_ad_title text DEFAULT NULL,_ad_tagline text DEFAULT NULL,_ad_cta text DEFAULT NULL,_ad_link text DEFAULT NULL,_ad_rating numeric DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n community_news%ROWTYPE; _cid uuid; _chat uuid; _image text; BEGIN IF NOT (has_role(auth.uid(),'admin') OR is_super_admin()) THEN RAISE EXCEPTION 'Admins only'; END IF; SELECT * INTO n FROM community_news WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Not found'; END IF; IF NOT _approve THEN UPDATE community_news SET status='rejected',reviewed_by=auth.uid(),reviewed_at=now() WHERE id=_id; INSERT INTO news_notifications(user_id,news_id,title,body) VALUES(n.author_id,_id,'News not published','Your news "'||n.title||'" doesn''t meet our community standards.'); RETURN 'rejected'; END IF; IF NOT n.watermarked THEN RAISE EXCEPTION 'This older recording must be recaptured with the FindMit watermark before publication'; END IF; _cid:=ensure_news_community(n.community_name,n.author_id); SELECT discussion_chat_id INTO _chat FROM communities WHERE id=_cid; IF _ad_link LIKE '/ad/%' THEN SELECT media_path INTO _image FROM shop_ads WHERE id::text=substring(_ad_link from 5) AND status='active' AND expires_at>now() AND media_type='image'; END IF; UPDATE community_news SET status='approved',community_id=_cid,reviewed_by=auth.uid(),reviewed_at=now(),ad_title=nullif(trim(_ad_title),''),ad_tagline=nullif(trim(_ad_tagline),''),ad_cta=nullif(trim(_ad_cta),''),ad_link=nullif(trim(_ad_link),''),ad_rating=_ad_rating,ad_image_path=_image WHERE id=_id; INSERT INTO messages(chat_id,sender_id,message_type,content,body) VALUES(_chat,n.author_id,'news',_id::text,n.title); UPDATE chats SET last_message='📰 '||n.title,last_message_at=now() WHERE id=_chat; INSERT INTO news_notifications(user_id,news_id,title,body) VALUES(n.author_id,_id,'News published','Your news "'||n.title||'" is now live.'); RETURN 'approved'; END $$;
UPDATE public.community_news n SET ad_image_path=a.media_path FROM public.shop_ads a WHERE n.ad_link='/ad/'||a.id::text AND a.media_type='image';